        .unwrap();
        let mut declaration = programs[0].types[0].clone();
        declaration.name = "ImportedRow".to_owned();
        let expression = default_expr(&rewritten, &[("ImportedRow", &declaration)], true).unwrap();
        let ExprKind::Call {
